(function(E){ const x = E["exam-03"] = E["exam-03"] || {units:{}}; (x.units = x.units || {})["x03-r2"] = {"id":"x03-r2","patterns":["RA-tech","GT2-policy","GT2-business","PARA-research","PARA-rules"],"title":{"en":"Reading 2: Passage 2 / Section 2","tr":"Reading 2: Passage 2 / Section 2","fa":"Reading ۲: متن ۲ (Passage 2) / بخش ۲ (Section 2)"},"objective":{"en":"In this lesson you will learn to decide TRUE, FALSE or NOT GIVEN about a report on city transport, paying attention to what happened first and what happened later, and to complete eight notes with single words from the passage.","tr":"Bu derste kent ulaşımı hakkındaki bir rapora dair TRUE, FALSE ya da NOT GIVEN kararı vermeyi, önce ne olduğuna ve sonra ne olduğuna dikkat ederek, ve sekiz notu metindeki tek kelimelerle tamamlamayı öğreneceksin.","fa":"در این درس یاد می‌گیری درباره‌ی گزارشی از حمل‌ونقل شهری بین TRUE، FALSE و NOT GIVEN تصمیم بگیری، با دقت به اینکه اول چه شد و بعد چه شد، و هشت یادداشت را با تک‌کلمه‌هایی از متن کامل کنی."},"objectiveGT":{"en":"In this lesson you will learn to complete sentences from a first-day guide with no more than two words, and notes from a manager’s checklist with one word, copying the text exactly.","tr":"Bu derste ilk gün rehberinden cümleleri en fazla iki kelimeyle ve bir yöneticinin kontrol listesinden notları tek kelimeyle, metni aynen kopyalayarak tamamlamayı öğreneceksin.","fa":"در این درس یاد می‌گیری جمله‌هایی را از یک راهنمای روز اول با حداکثر دو کلمه و یادداشت‌هایی را از فهرست کارهای یک مدیر با یک کلمه کامل کنی و متن را دقیق کپی کنی."},"sessions":[["explain"],["drill"],["exit"]],"explain":{"title":{"en":"Reading Passage 2: a city transport report","tr":"Reading Passage 2: bir kent ulaşımı raporu","fa":"Reading Passage 2: گزارشی درباره‌ی حمل‌ونقل شهری"},"objective":{"en":"In this lesson you will learn to decide TRUE, FALSE or NOT GIVEN about a report on city transport, paying attention to what happened first and what happened later, and to complete eight notes with single words from the passage.","tr":"Bu derste kent ulaşımı hakkındaki bir rapora dair TRUE, FALSE ya da NOT GIVEN kararı vermeyi, önce ne olduğuna ve sonra ne olduğuna dikkat ederek, ve sekiz notu metindeki tek kelimelerle tamamlamayı öğreneceksin.","fa":"در این درس یاد می‌گیری درباره‌ی گزارشی از حمل‌ونقل شهری بین TRUE، FALSE و NOT GIVEN تصمیم بگیری، با دقت به اینکه اول چه شد و بعد چه شد، و هشت یادداشت را با تک‌کلمه‌هایی از متن کامل کنی."},"stats":[{"label":{"en":"Questions","tr":"Soru","fa":"سؤال"},"value":"13"},{"label":{"en":"Time","tr":"Süre","fa":"زمان"},"value":{"en":"20 min","tr":"20 dk","fa":"۲۰ دقیقه"}},{"label":{"en":"Notes","tr":"Not","fa":"یادداشت"},"value":"8"}],"context":{"eyebrow":{"en":"1 The context","tr":"1 Bağlam","fa":"۱ بافت"},"head":{"en":"This exam: buses and bikes in a growing city","tr":"Bu sınav: büyüyen bir kentte otobüsler ve bisikletler","fa":"این آزمون: اتوبوس و دوچرخه در یک شهر رو به رشد"},"intro":{"en":"Technology and cities are a frequent Academic Reading subject. Reports like this one describe a problem, a solution, the difficulties and the results, and they often quote research carefully, with words such as \"appears\" and \"may\".","tr":"Teknoloji ve kentler Academic Reading’in sık konularındandır. Bunun gibi raporlar bir sorunu, bir çözümü, zorlukları ve sonuçları anlatır; araştırmayı çoğu zaman \"appears\" ve \"may\" gibi kelimelerle temkinli biçimde aktarır.","fa":"فناوری و شهر موضوع پرتکرار Academic Reading است. گزارش‌هایی مثل این یک مشکل، یک راه‌حل، دشواری‌ها و نتیجه‌ها را شرح می‌دهند و پژوهش را اغلب محتاطانه و با کلمه‌هایی مثل «appears» و «may» نقل می‌کنند."},"technique":{"en":"2 The technique","tr":"2 Teknik","fa":"۲ تکنیک"},"labels":{"asks":{"en":"What this part is about","tr":"Bu kısım ne hakkında","fa":"این بخش درباره‌ی چیست"},"fields":{"en":"Headings you will see","tr":"Göreceğin başlıklar","fa":"عنوان‌هایی که می‌بینی"},"words":{"en":"Words that carry the answers","tr":"Cevabı taşıyan kelimeler","fa":"کلمه‌هایی که جواب را می‌آورند"},"a":{"en":"On the paper","tr":"Kâğıtta","fa":"روی برگه"},"b":{"en":"What you hear or read","tr":"Duyduğun ya da okuduğun","fa":"چیزی که می‌شنوی یا می‌خوانی"},"traps":{"en":"Traps","tr":"Tuzaklar","fa":"دام‌ها"},"example":{"en":"Example","tr":"Örnek","fa":"نمونه"},"ideas":{"en":"Ideas","tr":"Fikirler","fa":"ایده‌ها"}},"cards":[{"id":"x03-r2-ctx","exam":true,"patterns":["RA-tech","PARA-research","TR-hedge"],"often":{"pattern":"RA-tech","n":18,"of":120,"label":{"en":"Comes up often in the real exam: 18 of the last 120 passages","tr":"Gerçek sınavda sık çıkar: son 120 metnin 18’inde","fa":"در آزمون واقعی زیاد می‌آید: در ۱۸ متن از ۱۲۰ متنِ اخیر"}},"title":{"en":"Transport in a growing city","tr":"Büyüyen bir kentte ulaşım","fa":"حمل‌ونقل در یک شهر رو به رشد"},"asks":{"en":"A report on how one fast-growing city tackled traffic: the failed road-building approach, a new bus system, a bike-share scheme, the problems met along the way and what researchers found.","tr":"Hızla büyüyen bir kentin trafikle nasıl mücadele ettiğine dair bir rapor: başarısız yol yapımı yaklaşımı, yeni bir otobüs sistemi, bir bisiklet paylaşım programı, yolda karşılaşılan sorunlar ve araştırmacıların bulguları.","fa":"گزارشی درباره‌ی اینکه یک شهر پررشد چطور با ترافیک کنار آمد: راه‌حلِ ناموفقِ ساختن جاده، یک سیستم اتوبوس تازه، طرح دوچرخه‌ی اشتراکی، مشکل‌هایی که پیش آمد و یافته‌های پژوهشگران."},"fields":["The problem","Building roads","The bus system","Early difficulties","Bikes","Weather and opposition","Research findings","Next steps"],"words":[{"a":"congested","b":"full of traffic / jammed","tr":"tıkalı","fa":"پرترافیک"},{"a":"flyover","b":"a road built over another road","tr":"üst geçit","fa":"روگذر"},{"a":"priority","b":"going first / more important","tr":"öncelik","fa":"اولویت"},{"a":"dedicated lane","b":"a lane only for buses","tr":"özel şerit","fa":"خط ویژه"},{"a":"boarding","b":"getting on","tr":"binme","fa":"سوار شدن"},{"a":"resent","b":"feel angry about","tr":"içerlemek","fa":"دلخور بودن"},{"a":"enforcement","b":"making people obey the rules (cameras, fines)","tr":"kuralları uygulatma","fa":"اجرای قانون"},{"a":"docking station","b":"where shared bikes are left","tr":"bisiklet istasyonu","fa":"ایستگاه دوچرخه"},{"a":"opposition","b":"people who are against it","tr":"muhalefet, karşı çıkanlar","fa":"مخالفت"},{"a":"feeder route","b":"a service that brings people to a main line","tr":"besleyici hat","fa":"خط تغذیه‌کننده"},{"a":"cautiously positive","b":"mostly pleased but careful","tr":"temkinli biçimde olumlu","fa":"خوش‌بین ولی محتاط"},{"a":"within walking distance","b":"close enough to walk to","tr":"yürüme mesafesinde","fa":"در فاصله‌ی پیاده‌روی"}],"traps":[{"en":"\"For a short time... However, within a few years...\" A statement about the long term can be FALSE even though the first result was good.","tr":"\"Kısa bir süre... Ancak birkaç yıl içinde...\" İlk sonuç iyi olsa bile uzun vadeyle ilgili bir ifade FALSE olabilir.","fa":"«برای مدتی کوتاه... اما ظرف چند سال...». جمله‌ای درباره‌ی درازمدت ممکن است FALSE باشد، حتی اگر نتیجه‌ی اول خوب بوده."},{"en":"Researchers often hedge: \"appears to have improved\", \"may partly be the result of\". A statement that says something was proved goes beyond the text.","tr":"Araştırmacılar çoğu zaman temkinli konuşur: \"iyileşmiş görünüyor\", \"kısmen ... sonucu olabilir\". Bir şeyin kanıtlandığını söyleyen ifade metnin ötesine geçer.","fa":"پژوهشگرها اغلب محتاطانه حرف می‌زنند: «به نظر می‌رسد بهتر شده»، «ممکن است تا حدی نتیجه‌ی ... باشد». جمله‌ای که می‌گوید چیزی ثابت شده، از متن جلوتر می‌رود."}],"example":{"text":"\"The new timetable worked well for the first month, but by the end of the year most trains were late again.\"","item":"Statement: The new timetable made trains punctual for a long period. TRUE, FALSE or NOT GIVEN?","answer":"FALSE","why":{"en":"\"By the end of the year most trains were late again\": the long-term result contradicts the statement.","tr":"\"Yılın sonunda trenlerin çoğu yine gecikiyordu\": uzun vadeli sonuç ifadeyle çelişiyor.","fa":"«تا آخر سال بیشتر قطارها دوباره تأخیر داشتند»: نتیجه‌ی درازمدت با جمله تناقض دارد."}}},{"id":"RA-tech-research","ctx":["RA-tech"],"title":{"en":"Technology, business and cities: experts compared","tr":"Teknoloji, iş dünyası ve şehirler: uzman görüşleri","fa":"فناوری، کسب‌وکار و شهرها: مقایسه‌ی نظر متخصص‌ها"},"asks":{"en":"A report on technology, business or cities that compares experts’ views: driverless cars, robot referees, green roofs, company boards. Matching features links each view to an expert; multiple choice tests why the writer gives an example.","tr":"Teknoloji, iş dünyası ya da şehirler üzerine uzman görüşlerini karşılaştıran bir rapor: sürücüsüz arabalar, robot hakemler, yeşil çatılar, şirket yönetim kurulları. Özellik eşleştirme her görüşü bir uzmana bağlar; çoktan seçmeli sorular yazarın bir örneği neden verdiğini sınar.","fa":"گزارشی درباره‌ی فناوری، کسب‌وکار یا شهرها که نظر متخصص‌ها را مقایسه می‌کند: خودروی بی‌راننده، داور رباتیک، بام سبز، هیئت‌مدیره‌ی شرکت‌ها. جورکردن ویژگی‌ها هر نظر را به یک متخصص وصل می‌کند؛ سؤال چندگزینه‌ای می‌پرسد نویسنده چرا مثالی را آورده."},"fields":["Which expert warns about the cost?","Which company was the first to try it?","The writer mentions the stadium in order to...","Green roofs are most useful when... (sentence ending)"],"words":[{"a":"benefit","b":"advantage / gain","tr":"yarar","fa":"سود"},{"a":"drawback","b":"disadvantage / downside","tr":"dezavantaj","fa":"عیب"},{"a":"reduce","b":"cut / bring down","tr":"azaltmak","fa":"کاهش دادن"},{"a":"investment","b":"money spent at the start","tr":"yatırım","fa":"سرمایه‌گذاری"},{"a":"adopt","b":"start using / take up","tr":"benimsemek","fa":"به کار گرفتن"},{"a":"reliable","b":"can be trusted / works every time","tr":"güvenilir","fa":"قابل اعتماد"},{"a":"regulation","b":"rules / the law","tr":"düzenleme","fa":"مقررات"},{"a":"consumers","b":"customers / the public","tr":"tüketiciler","fa":"مصرف‌کننده‌ها"},{"a":"predicts","b":"expects / forecasts","tr":"öngörür","fa":"پیش‌بینی می‌کند"},{"a":"warns","b":"points out the risk","tr":"uyarır","fa":"هشدار می‌دهد"},{"a":"widespread","b":"common / in many places","tr":"yaygın","fa":"گسترده"},{"a":"enthusiastic","b":"very positive about it","tr":"hevesli","fa":"مشتاق"}],"traps":[{"en":"Two experts mention cost; only one says it is the main problem. Match the whole statement.","tr":"İki uzman maliyetten söz eder; yalnızca biri asıl sorunun bu olduğunu söyler. İfadenin tamamını eşleştir.","fa":"دو متخصص از هزینه حرف می‌زنند؛ فقط یکی می‌گوید مشکل اصلی همین است. کل جمله را جور کن."},{"en":"Writer’s purpose: the answer is why the example is there, not what the example says.","tr":"Yazarın amacı: cevap örneğin ne söylediği değil, neden orada olduğudur.","fa":"هدف نویسنده: جواب این است که چرا مثال آنجاست، نه اینکه مثال چه می‌گوید."}],"example":{"text":"The engineer Maria Costa believes driverless buses will be common within ten years. The economist Paul Hart is less sure: the technology may be ready, he says, but the law is not.","item":"Who thinks that rules and laws will slow progress?  A Maria Costa   B Paul Hart","answer":"B","why":{"en":"\"The law is not [ready]\" = regulation will slow it down. That is Hart’s view.","tr":"\"Yasa hazır değil\" = düzenlemeler ilerlemeyi yavaşlatacak. Bu Hart’ın görüşü.","fa":"«قانون آماده نیست» = مقررات پیشرفت را کند می‌کند. این نظر هارت است."}},"track":"academic","general":true,"patterns":["RA-tech"],"often":{"pattern":"RA-tech","n":18,"of":120,"label":{"en":"Comes up often in the real exam: 18 of the last 120 passages","tr":"Gerçek sınavda sık çıkar: son 120 metnin 18’inde","fa":"در آزمون واقعی زیاد می‌آید: در ۱۸ متن از ۱۲۰ متنِ اخیر"}}}]},"points":[{"eyebrow":{"en":"In the exam","tr":"Sınavda","fa":"در آزمون"},"head":{"en":"Statements first, then notes","tr":"Önce ifadeler, sonra notlar","fa":"اول جمله‌ها، بعد یادداشت‌ها"},"body":{"en":"Questions 14-18 are TRUE, FALSE or NOT GIVEN about the first half of the passage. Questions 19-26 are notes on the second half: ONE WORD ONLY from the passage for each gap.","tr":"Soru 14-18 metnin ilk yarısıyla ilgili TRUE, FALSE ya da NOT GIVEN ifadeleridir. Soru 19-26 ikinci yarıyla ilgili notlardır: her boşluk için metinden YALNIZCA BİR KELİME.","fa":"سؤال‌های ۱۴ تا ۱۸ جمله‌های TRUE، FALSE یا NOT GIVEN درباره‌ی نیمه‌ی اول متن‌اند. سؤال‌های ۱۹ تا ۲۶ یادداشت‌هایی درباره‌ی نیمه‌ی دوم‌اند: برای هر جای خالی فقط یک کلمه از متن."}},{"eyebrow":{"en":"The method","tr":"Yöntem","fa":"روش"},"head":{"en":"Watch the time words","tr":"Zaman kelimelerine dikkat et","fa":"حواست به کلمه‌های زمانی باشد"},"steps":[{"en":"Underline time words in each statement: at first, for many years, now, always.","tr":"Her ifadedeki zaman kelimelerinin altını çiz: at first, for many years, now, always.","fa":"زیر کلمه‌های زمانی هر جمله خط بکش: at first، for many years، now، always."},{"en":"Find the sentence and check whether it is true for the same period of time.","tr":"Cümleyi bul ve aynı zaman dilimi için doğru olup olmadığını kontrol et.","fa":"جمله را پیدا کن و ببین برای همان دوره‌ی زمانی درست است یا نه."},{"en":"For the notes, use the headings to find the paragraph, then copy one word exactly.","tr":"Notlar için paragrafı başlıklarla bul, sonra tek kelimeyi aynen kopyala.","fa":"برای یادداشت‌ها پاراگراف را با عنوان‌ها پیدا کن و بعد یک کلمه را دقیق کپی کن."}]},{"eyebrow":{"en":"The trap","tr":"Tuzak","fa":"دام"},"head":{"en":"FALSE or NOT GIVEN?","tr":"FALSE mı NOT GIVEN mı?","fa":"FALSE یا NOT GIVEN؟"},"table":{"headers":{"en":["The text","The answer"],"tr":["Metin","Cevap"],"fa":["متن","جواب"]},"rows":[["says the same thing in other words","TRUE"],["says the opposite, or a different fact on the same point","FALSE"],["says nothing about this point","NOT GIVEN"]]}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"One statement, step by step","tr":"Bir ifade, adım adım","fa":"یک جمله، قدم به قدم"},"instruction":"Do the following statements agree with the information given in the passage?","text":"\"When the tram line opened, many shopkeepers opposed it. Ten years later, most of them say it has brought them more customers.\"","item":"Statement: Shopkeepers have always supported the tram line.","answer":"FALSE","walk":[{"en":"Underline the time word: always.","tr":"Zaman kelimesinin altını çiz: always.","fa":"زیر کلمه‌ی زمانی خط بکش: always."},{"en":"Find the place: \"when the tram line opened, many shopkeepers opposed it\".","tr":"Yeri bul: \"tramvay hattı açıldığında birçok esnaf karşı çıktı\".","fa":"جایش را پیدا کن: «وقتی خط تراموا باز شد، خیلی از مغازه‌دارها مخالفت کردند»."},{"en":"They did not always support it: FALSE.","tr":"Her zaman desteklemediler: FALSE.","fa":"همیشه حمایت نمی‌کردند: FALSE."}]},"quick":{"prompt":"Text: \"Noise levels appear to have fallen slightly.\" Statement: \"Noise levels have fallen a great deal.\" TRUE, FALSE or NOT GIVEN?","options":["FALSE","TRUE","NOT GIVEN"],"correct":0,"why":{"en":"\"Slightly\" contradicts \"a great deal\"; \"appears\" adds that even this is not certain.","tr":"\"Slightly\", \"a great deal\" ile çelişiyor; \"appears\" bunun bile kesin olmadığını ekliyor.","fa":"«slightly» با «a great deal» تناقض دارد؛ «appears» هم می‌گوید حتی این قطعی نیست."}},"remember":{"en":"Check the time words in each statement, and copy note answers exactly, one word each.","tr":"Her ifadedeki zaman kelimelerini kontrol et ve not cevaplarını aynen, her biri tek kelime olarak kopyala.","fa":"کلمه‌های زمانی هر جمله را چک کن و جواب یادداشت‌ها را دقیق، هر کدام یک کلمه، کپی کن."},"type":"explain","id":"c-x03-r2-e","course":"ielts-exams","exam":"exam-03","unit":"x03-r2"},"drill":{"type":"drill","skill":"reading","part":"Academic Reading Passage 2","title":{"en":"Moving a growing city","tr":"Büyüyen bir kenti hareket ettirmek","fa":"جابه‌جا کردنِ یک شهر رو به رشد"},"timed":20,"ctx":["RA-tech"],"intro":"You should spend about 20 minutes on Questions 14-26, which are based on Reading Passage 2 below.","passage":"Moving a growing city\n\nThirty years ago, the city at the centre of this study was home to around two million people. Today it has more than six million, and the number is still rising. For most of that period, transport planning struggled to keep up. Motorbikes, cheap to buy and easy to park, became the main way of getting around, and by the early 2010s the average speed of traffic in the centre at rush hour had fallen to little more than walking pace. The cost was not only lost time: noise and fumes from millions of engines made the centre an unpleasant place to live, and road accidents were rising every year.\n\nThe city's first response was to build. Main roads were widened, and a series of flyovers was constructed over the busiest junctions. For a short time, journeys became quicker. Within a few years, however, the new roads were as crowded as the old ones. Transport researchers have a name for this effect, induced demand: when a road becomes faster, more people decide to use it, until it is congested once again. The city had spent heavily and gained very little.\n\nThe turning point came with a decision to give priority not to vehicles but to people. The centrepiece of the new plan was a bus rapid transit system, usually known as BRT. Unlike ordinary buses, BRT buses run in their own lanes in the middle of the main roads, separated from other traffic. Passengers wait at proper stations rather than at the roadside, and they pay before they get on, by touching a card at the station gate, so that boarding takes seconds rather than minutes. The floors of the stations are level with the floors of the buses, which makes them easy to use for people with prams, wheelchairs or heavy bags.\n\nThe first line, running for twenty-two kilometres along the city's busiest road, opened six years ago. Journey times along the route fell by about a third, and within two years the line was carrying more passengers than the planners had expected. There were difficulties at first. Many car drivers resented losing road space, and in the early months private cars regularly drove into the bus lanes, slowing everyone down. The problem was only brought under control when cameras were installed and drivers began to receive fines. Since then, the lanes have been largely kept clear, and the buses keep to a regular timetable even at the busiest times of day.\n\nThe second element of the plan was the bicycle. A public bike-share scheme was set up, with docking stations close to every BRT station, so that passengers could cover the first and last kilometre of their journey without a car or motorbike. The scheme proved most popular with students, who used it for short trips across the university district. Surveys showed, however, that far fewer women than men were using the bikes, and that the main reason was worries about safety. In response, the city began to build cycle lanes separated from the traffic by low concrete kerbs, and the number of women riding has risen since.\n\nNot everything has gone smoothly. The climate is a problem for both buses and bikes: in the hot season the heat makes cycling unpleasant, and in the wet season heavy rain floods some stations. There was also strong opposition from the owners of the private minibuses that had carried most of the city's passengers before BRT arrived, and who saw their income disappearing. After long negotiations, some of these operators now run feeder routes, bringing passengers from the outer districts to the BRT stations.\n\nResearchers who have studied the scheme are cautiously positive. A survey of passengers found that a large share had previously travelled by motorbike, which suggests that the system is attracting people out of private vehicles rather than simply taking passengers from other buses. Air quality along the main corridor appears to have improved slightly, although the researchers point out that this may partly be the result of cleaner engines rather than fewer vehicles.\n\nThe city now plans a second BRT line and a larger bike network, and several neighbouring cities have sent officials to learn from its experience. Planners have also learned that transport cannot be separated from the use of land. New housing and offices are being built around the stations, so that more people can live and work within walking distance of a fast route. If that succeeds, the city may finally have found a way of moving millions of people without bringing its streets to a standstill.","groups":[{"instruction":"Questions 14-18. Do the following statements agree with the information given in Reading Passage 2? In boxes 14-18 on your answer sheet, write TRUE if the statement agrees with the information, FALSE if the statement contradicts the information, NOT GIVEN if there is no information on this.","qtype":"tfng","questions":[{"n":14,"kind":"tfng","prompt":"The city’s population has more than doubled in the last thirty years.","correct":"TRUE","evidence":"Today it has more than six million","why":{"en":"From around two million to \"more than six million\": more than double.","tr":"Yaklaşık iki milyondan \"altı milyonun üzerine\": iki katından fazla.","fa":"از حدود دو میلیون به «بیش از شش میلیون»: بیش از دو برابر."},"trap":["TR-paraphrase"]},{"n":15,"kind":"tfng","prompt":"Widening the roads reduced traffic jams for many years.","correct":"FALSE","evidence":"Within a few years, however, the new roads were as crowded as the old ones","why":{"en":"Journeys were quicker \"for a short time\"; \"within a few years\" the roads were crowded again.","tr":"Yolculuklar \"kısa bir süre\" hızlandı; \"birkaç yıl içinde\" yollar yine kalabalıklaştı.","fa":"سفرها «برای مدتی کوتاه» سریع‌تر شدند؛ «ظرف چند سال» جاده‌ها دوباره شلوغ شدند."},"trap":["TR-NGvsF","PARA-cause"]},{"n":16,"kind":"tfng","prompt":"BRT passengers pay for their journey before they get on the bus.","correct":"TRUE","evidence":"they pay before they get on","why":{"en":"\"They pay before they get on, by touching a card at the station gate.\"","tr":"\"Binmeden önce, istasyon girişinde kart okutarak öderler.\"","fa":"«قبل از سوار شدن، با زدن کارت در ورودی ایستگاه پول می‌دهند»."},"trap":["TR-NGvsF"]},{"n":17,"kind":"tfng","prompt":"Car drivers welcomed the bus lanes from the beginning.","correct":"FALSE","evidence":"Many car drivers resented losing road space","why":{"en":"\"Many car drivers resented losing road space\", and cars drove into the bus lanes.","tr":"\"Birçok sürücü yol alanını kaybetmeye içerledi\" ve arabalar otobüs şeritlerine girdi.","fa":"«خیلی از راننده‌ها از دست دادن فضای جاده را نمی‌پسندیدند» و ماشین‌ها وارد خط اتوبوس می‌شدند."},"trap":["TR-paraphrase"]},{"n":18,"kind":"tfng","prompt":"The first BRT line was built in less than a year.","correct":"NOT GIVEN","evidence":"The first line, running for twenty-two kilometres along the city's busiest road, opened six years ago","why":{"en":"The passage gives the length and when the line opened, not how long it took to build.","tr":"Metin hattın uzunluğunu ve ne zaman açıldığını veriyor, yapımının ne kadar sürdüğünü değil.","fa":"متن طول خط و زمان افتتاحش را می‌گوید، نه اینکه ساختنش چقدر طول کشید."},"trap":["TR-NGvsF"]}]},{"instruction":"Questions 19-26. Complete the notes below. Choose ONE WORD ONLY from the passage for each answer. Write your answers in boxes 19-26 on your answer sheet.","qtype":"note","notesTitle":"Bikes, problems and the future","questions":[{"n":19,"kind":"gap","prompt":"Bike-share · lets passengers ride the first and last ___ of a journey","accept":["kilometre"],"limit":1,"evidence":"cover the first and last kilometre of their journey","why":{"en":"\"Cover the first and last kilometre of their journey without a car or motorbike.\"","tr":"\"Yolculuklarının ilk ve son kilometresini araba ya da motosiklet olmadan kat etmek.\"","fa":"«کیلومتر اول و آخر سفرشان را بدون ماشین یا موتور طی کنند»."},"trap":["TR-paraphrase"]},{"n":20,"kind":"gap","prompt":"Bike-share · most popular with ___","accept":["students"],"limit":1,"evidence":"most popular with students","why":{"en":"\"The scheme proved most popular with students.\"","tr":"\"Program en çok öğrenciler arasında popüler oldu.\"","fa":"«این طرح بیشتر از همه بین دانشجوها محبوب شد»."},"trap":["TR-plural"]},{"n":21,"kind":"gap","prompt":"Bike-share · fewer women used it because of worries about ___","accept":["safety"],"limit":1,"evidence":"the main reason was worries about safety","why":{"en":"\"The main reason was worries about safety.\"","tr":"\"Ana neden güvenlik kaygılarıydı.\"","fa":"«دلیل اصلی نگرانی درباره‌ی امنیت بود»."},"trap":["TR-paraphrase"]},{"n":22,"kind":"gap","prompt":"Bike-share · new cycle lanes are separated from traffic by low concrete ___","accept":["kerbs"],"limit":1,"evidence":"separated from the traffic by low concrete kerbs","why":{"en":"\"Separated from the traffic by low concrete kerbs.\" Plural.","tr":"\"Trafikten alçak beton bordürlerle ayrılmış.\" Çoğul.","fa":"«با جدول‌های بتنی کوتاه از ترافیک جدا شده». جمع."},"trap":["TR-plural","TR-limit"]},{"n":23,"kind":"gap","prompt":"Problems · in the wet season, heavy ___ floods some stations","accept":["rain"],"limit":1,"evidence":"heavy rain floods some stations","why":{"en":"\"In the wet season heavy rain floods some stations.\"","tr":"\"Yağışlı mevsimde şiddetli yağmur bazı istasyonları su basıyor.\"","fa":"«در فصل بارانی، باران شدید بعضی ایستگاه‌ها را آب می‌گیرد»."},"trap":["TR-paraphrase"]},{"n":24,"kind":"gap","prompt":"Problems · strong opposition from owners of private ___","accept":["minibuses"],"limit":1,"evidence":"the owners of the private minibuses","why":{"en":"\"The owners of the private minibuses that had carried most of the city’s passengers.\" Plural.","tr":"\"Kentin yolcularının çoğunu taşıyan özel minibüslerin sahipleri.\" Çoğul.","fa":"«صاحبان مینی‌بوس‌های خصوصی که بیشتر مسافران شهر را جابه‌جا می‌کردند». جمع."},"trap":["TR-plural","TR-paraphrase"]},{"n":25,"kind":"gap","prompt":"Problems · some owners now run ___ routes that bring passengers to BRT stations","accept":["feeder"],"limit":1,"evidence":"some of these operators now run feeder routes","why":{"en":"\"Some of these operators now run feeder routes.\"","tr":"\"Bu işletmecilerin bazıları artık besleyici hatlar işletiyor.\"","fa":"«بعضی از این گرداننده‌ها حالا خط‌های تغذیه‌کننده را اداره می‌کنند»."},"trap":["TR-paraphrase"]},{"n":26,"kind":"gap","prompt":"The future · new homes and offices are being built around the ___","accept":["stations"],"limit":1,"evidence":"New housing and offices are being built around the stations","why":{"en":"\"New housing and offices are being built around the stations.\" Plural.","tr":"\"İstasyonların çevresine yeni konutlar ve ofisler yapılıyor.\" Çoğul.","fa":"«دور ایستگاه‌ها خانه و دفتر تازه ساخته می‌شود». جمع."},"trap":["TR-plural","PARA-research"]}]}],"id":"c-x03-r2-d","course":"ielts-exams","exam":"exam-03","unit":"x03-r2"},"exit":{"type":"exit","items":[{"tests":"word","point":1,"prompt":"\"Many drivers resented the new bus lanes.\" Resented means...","options":["paid for","used often","felt angry about"],"correct":2,"why":{"en":"To resent something = to feel angry or bitter about it.","tr":"Bir şeye resent etmek = ona öfke ya da kırgınlık duymak.","fa":"resent کردن یعنی از چیزی دلخور یا عصبانی بودن."}},{"tests":"paraphrase","point":1,"prompt":"A note says \"people who were against the plan\". Which word would you look for in a passage?","options":["enforcement","opposition","priority"],"correct":1,"why":{"en":"Opposition = people who are against something.","tr":"Opposition = bir şeye karşı olan insanlar.","fa":"opposition یعنی کسانی که با چیزی مخالف‌اند."}},{"tests":"method","point":2,"prompt":"Statement: \"For several years the new road made journeys faster.\" Which part should you check most carefully?","options":["for several years","the new road","journeys"],"correct":0,"why":{"en":"The time phrase is where TRUE and FALSE usually differ: was it several years, or only a short time?","tr":"TRUE ile FALSE genelde zaman ifadesinde ayrılır: birkaç yıl mı, yoksa kısa bir süre mi?","fa":"TRUE و FALSE معمولاً در عبارت زمانی فرق می‌کنند: چند سال بود یا فقط مدتی کوتاه؟"}},{"tests":"trap","point":3,"prompt":"Text: \"At first the scheme was unpopular, but now it has wide support.\" Statement: \"The scheme has always been popular.\"","options":["TRUE","NOT GIVEN","FALSE"],"correct":2,"why":{"en":"\"At first... unpopular\" contradicts \"always popular\".","tr":"\"Başta... sevilmiyordu\", \"her zaman popüler\" ile çelişiyor.","fa":"«اول... محبوب نبود» با «همیشه محبوب بوده» تناقض دارد."}},{"tests":"trap","point":3,"prompt":"Text: \"The new line opened in 2019.\" Statement: \"The new line was finished ahead of schedule.\"","options":["TRUE","NOT GIVEN","FALSE"],"correct":1,"why":{"en":"The opening date is given, but nothing about the schedule.","tr":"Açılış tarihi veriliyor ama takvim hakkında hiçbir şey yok.","fa":"تاریخ افتتاح گفته شده، اما درباره‌ی برنامه‌ی زمانی چیزی نیست."}}],"id":"c-x03-r2-x","course":"ielts-exams","exam":"exam-03","unit":"x03-r2"},"gt":{"explain":{"title":{"en":"GT Reading Section 2: workplace guides","tr":"GT Reading Section 2: iş yeri rehberleri","fa":"GT Reading Section 2: راهنماهای محل کار"},"objective":{"en":"In this lesson you will learn to complete sentences from a first-day guide with no more than two words, and notes from a manager’s checklist with one word, copying the text exactly.","tr":"Bu derste ilk gün rehberinden cümleleri en fazla iki kelimeyle ve bir yöneticinin kontrol listesinden notları tek kelimeyle, metni aynen kopyalayarak tamamlamayı öğreneceksin.","fa":"در این درس یاد می‌گیری جمله‌هایی را از یک راهنمای روز اول با حداکثر دو کلمه و یادداشت‌هایی را از فهرست کارهای یک مدیر با یک کلمه کامل کنی و متن را دقیق کپی کنی."},"stats":[{"label":{"en":"Questions","tr":"Soru","fa":"سؤال"},"value":"13"},{"label":{"en":"Texts","tr":"Metin","fa":"متن"},"value":"2"},{"label":{"en":"Word limit","tr":"Kelime sınırı","fa":"سقف کلمه"},"value":{"en":"2 / 1 words","tr":"2 / 1 kelime","fa":"۲ / ۱ کلمه"}}],"context":{"eyebrow":{"en":"1 The context","tr":"1 Bağlam","fa":"۱ بافت"},"head":{"en":"This exam: a hospital office and a cinema","tr":"Bu sınav: bir hastane ofisi ve bir sinema","fa":"این آزمون: دفتر یک بیمارستان و یک سینما"},"intro":{"en":"Section 2 always has two work texts. Workplace policies and procedures (what to do on your first day, what a manager must check) are among the commonest, and they are written as instructions.","tr":"Section 2’de her zaman iki iş metni vardır. İş yeri politikaları ve prosedürleri (ilk gün ne yapılacağı, bir yöneticinin neyi kontrol etmesi gerektiği) en yaygınlardandır ve talimat biçiminde yazılır.","fa":"Section 2 همیشه دو متن کاری دارد. سیاست‌ها و روال‌های محل کار (روز اول چه باید کرد، مدیر چه چیزی را باید چک کند) از رایج‌ترین‌ها هستند و به شکل دستورالعمل نوشته می‌شوند."},"technique":{"en":"2 The technique","tr":"2 Teknik","fa":"۲ تکنیک"},"labels":{"asks":{"en":"What this part is about","tr":"Bu kısım ne hakkında","fa":"این بخش درباره‌ی چیست"},"fields":{"en":"Headings you will see","tr":"Göreceğin başlıklar","fa":"عنوان‌هایی که می‌بینی"},"words":{"en":"Words that carry the answers","tr":"Cevabı taşıyan kelimeler","fa":"کلمه‌هایی که جواب را می‌آورند"},"a":{"en":"On the paper","tr":"Kâğıtta","fa":"روی برگه"},"b":{"en":"What you hear or read","tr":"Duyduğun ya da okuduğun","fa":"چیزی که می‌شنوی یا می‌خوانی"},"traps":{"en":"Traps","tr":"Tuzaklar","fa":"دام‌ها"},"example":{"en":"Example","tr":"Örnek","fa":"نمونه"},"ideas":{"en":"Ideas","tr":"Fikirler","fa":"ایده‌ها"}},"cards":[{"id":"x03-r2gt-ctx","exam":true,"patterns":["GT2-policy","GT2-business","PARA-rules"],"often":{"pattern":"GT2-policy","n":11,"of":55,"label":{"en":"Comes up often in the real exam: 11 of the last 55 texts","tr":"Gerçek sınavda sık çıkar: son 55 metnin 11’inde","fa":"در آزمون واقعی زیاد می‌آید: در ۱۱ متن از ۵۵ متنِ اخیر"}},"title":{"en":"A first day at work and a manager’s checklist","tr":"İşte ilk gün ve bir yöneticinin kontrol listesi","fa":"روز اول کار و فهرست کارهای یک مدیر"},"asks":{"en":"Section 2 is about work. Here: a guide telling new office staff what happens on their first day, and notes that tell cinema duty managers what to do before, during and after a shift.","tr":"Section 2 iş hayatıyla ilgilidir. Burada: yeni ofis çalışanlarına ilk günlerinde ne olacağını anlatan bir rehber ve sinema vardiya müdürlerine bir vardiyadan önce, sırasında ve sonra ne yapacaklarını söyleyen notlar.","fa":"Section 2 درباره‌ی کار است. این‌جا: راهنمایی که به کارمندان تازه‌ی اداری می‌گوید روز اولشان چه پیش می‌آید و یادداشت‌هایی که به مدیران شیفت یک سینما می‌گویند قبل، در طول و بعد از شیفت چه کنند."},"fields":["Arriving","Your morning","IT access","Lunch and parking","Before opening","Staffing","Complaints","Closing"],"words":[{"a":"report to","b":"go to and say you have arrived","tr":"... yanına gidip gelişini bildirmek","fa":"خود را معرفی کردن به"},{"a":"badge","b":"a card you wear to show who you are","tr":"yaka kartı","fa":"کارت شناسایی"},{"a":"mentor","b":"an experienced colleague who helps you","tr":"rehber çalışan, mentor","fa":"همکار راهنما"},{"a":"log in","b":"enter a computer system","tr":"sisteme giriş yapmak","fa":"وارد سیستم شدن"},{"a":"discounted","b":"cheaper than usual","tr":"indirimli","fa":"با تخفیف"},{"a":"waiting list","b":"a list of people waiting their turn","tr":"bekleme listesi","fa":"فهرست انتظار"},{"a":"minimum staffing","b":"the smallest number of staff allowed","tr":"asgari personel sayısı","fa":"حداقل تعداد کارکنان"},{"a":"record","b":"write down officially","tr":"kaydetmek","fa":"ثبت کردن"},{"a":"apologise","b":"say sorry","tr":"özür dilemek","fa":"عذرخواهی کردن"}],"traps":[{"en":"NO MORE THAN TWO WORDS: if the text says \"the new visitor car park\", you may need to leave out a word. Check the sentence still makes sense with your answer.","tr":"NO MORE THAN TWO WORDS: metin \"the new visitor car park\" diyorsa bir kelimeyi çıkarman gerekebilir. Cümlenin cevabınla hâlâ anlamlı olduğunu kontrol et.","fa":"NO MORE THAN TWO WORDS: اگر متن می‌گوید «the new visitor car park»، شاید لازم باشد یک کلمه را حذف کنی. چک کن جمله با جوابت هنوز معنی دارد."},{"en":"Two places with similar names (staff entrance, main entrance). The text tells you which one with a detail such as \"use the side door, not the main entrance\".","tr":"Benzer adlı iki yer (staff entrance, main entrance). Hangisi olduğunu metin bir ayrıntıyla söyler: \"use the side door, not the main entrance\" gibi.","fa":"دو جا با اسم‌های شبیه (staff entrance، main entrance). متن با یک جزئیات می‌گوید کدام است، مثلاً «use the side door, not the main entrance»."}],"example":{"text":"\"Uniforms are collected from the laundry room, not from the staff office.\"","item":"New staff collect their uniforms from the ___ (NO MORE THAN TWO WORDS)","answer":"laundry room","why":{"en":"Two words; the staff office is ruled out by \"not\".","tr":"İki kelime; personel ofisi \"not\" ile eleniyor.","fa":"دو کلمه؛ دفتر کارکنان با «not» رد می‌شود."}}},{"id":"GT2-policy","ctx":["GT2-policy"],"title":{"en":"Workplace policies and conditions","tr":"İş yeri politikaları ve çalışma koşulları","fa":"سیاست‌ها و شرایط محیط کار"},"asks":{"en":"A page from a staff handbook: parking, dress code, leave, absence, benefits or the complaints procedure. Questions test what staff must do, by when, and who they tell.","tr":"Bir personel el kitabından bir sayfa: otopark, kıyafet kuralı, izin, devamsızlık, yan haklar ya da şikâyet prosedürü. Sorular personelin ne yapması gerektiğini, ne zamana kadar ve kime haber vereceğini sınar.","fa":"صفحه‌ای از راهنمای کارکنان: پارکینگ، قانون پوشش، مرخصی، غیبت، مزایا یا روند رسیدگی به شکایت. سؤال‌ها می‌سنجند کارکنان چه باید بکنند، تا کی و به چه کسی خبر بدهند."},"fields":["Staff must inform their ___ before 9 a.m. if they are ill.","Holiday requests need ___ weeks’ notice.","Parking permits are issued by ___.","Jeans may be worn on ___."],"words":[{"a":"entitled to","b":"have the right to","tr":"... hakkı olmak","fa":"حق داشتن"},{"a":"annual leave","b":"holiday","tr":"yıllık izin","fa":"مرخصی سالانه"},{"a":"notice","b":"warning in advance","tr":"önceden haber","fa":"اطلاع قبلی"},{"a":"sick leave","b":"time off when you are ill","tr":"hastalık izni","fa":"مرخصی استعلاجی"},{"a":"permit","b":"an official permission card","tr":"izin kartı","fa":"مجوز"},{"a":"dress code","b":"rules about clothes","tr":"kıyafet kuralları","fa":"قانون پوشش"},{"a":"casual","b":"informal / relaxed","tr":"rahat, gündelik","fa":"غیررسمی"},{"a":"grievance","b":"a formal complaint","tr":"resmî şikâyet","fa":"شکایت رسمی"},{"a":"approve","b":"agree to / sign off","tr":"onaylamak","fa":"تأیید کردن"},{"a":"allowance","b":"money paid for something","tr":"ödenek","fa":"کمک‌هزینه"},{"a":"probation","b":"a trial period","tr":"deneme süresi","fa":"دوره‌ی آزمایشی"},{"a":"in writing","b":"by email or letter","tr":"yazılı olarak","fa":"به‌صورت کتبی"}],"traps":[{"en":"Who to tell: \"your line manager\" and \"HR\" are often named for different steps.","tr":"Kime haber verilir: \"bağlı olduğun yönetici\" ve \"İK\" çoğu zaman farklı adımlar için geçer.","fa":"به چه کسی خبر بدهی: «مدیر مستقیم» و «منابع انسانی» اغلب برای مرحله‌های مختلف نام برده می‌شوند."},{"en":"Periods: \"two weeks’ notice\" and \"within two weeks\" mean different things.","tr":"Süreler: \"iki hafta önceden haber\" ile \"iki hafta içinde\" farklı şeylerdir.","fa":"مدت‌ها: «دو هفته اطلاع قبلی» با «ظرف دو هفته» فرق دارد."}],"example":{"text":"If you cannot come to work because of illness, phone your line manager before 9 a.m. on the first day. HR only needs to be told if the absence lasts more than five working days.","item":"Staff who are ill must first contact their ___.   (NO MORE THAN TWO WORDS)","answer":"line manager","why":{"en":"The line manager is told first; HR only after five working days.","tr":"Önce bağlı olunan yöneticiye haber verilir; İK’ya ancak beş iş gününden sonra.","fa":"اول به مدیر مستقیم خبر می‌دهی؛ به منابع انسانی فقط بعد از پنج روز کاری."}},"track":"gt","general":true,"patterns":["GT2-policy"],"often":{"pattern":"GT2-policy","n":11,"of":55,"label":{"en":"Comes up often in the real exam: 11 of the last 55 texts","tr":"Gerçek sınavda sık çıkar: son 55 metnin 11’inde","fa":"در آزمون واقعی زیاد می‌آید: در ۱۱ متن از ۵۵ متنِ اخیر"}}},{"id":"GT2-business","ctx":["GT2-business"],"title":{"en":"Running a team or a small business","tr":"Bir ekibi ya da küçük bir işletmeyi yönetmek","fa":"اداره‌ی یک تیم یا یک کسب‌وکار کوچک"},"asks":{"en":"Workplace guides on meetings, projects, delegation, marketing, flexible working or types of training. Sentence and note completion test the advice and the steps.","tr":"Toplantılar, projeler, görev devri, pazarlama, esnek çalışma ya da eğitim türleri üzerine iş yeri rehberleri. Cümle ve not tamamlama tavsiyeleri ve adımları sınar.","fa":"راهنماهای محیط کار درباره‌ی جلسه، پروژه، واگذاری کار، بازاریابی، کار منعطف یا انواع آموزش. کامل کردن جمله و یادداشت توصیه‌ها و مرحله‌ها را می‌سنجد."},"fields":["Before a meeting, send the ___ to everyone.","Give tasks to staff who can do them ___.","Flexible hours must be agreed with your ___.","Training: on the job · external course · online"],"words":[{"a":"agenda","b":"list of points for the meeting","tr":"gündem","fa":"دستور جلسه"},{"a":"delegate","b":"give a task to someone else","tr":"görev devretmek","fa":"واگذار کردن"},{"a":"deadline","b":"the date it must be done by","tr":"son tarih","fa":"مهلت"},{"a":"budget","b":"the money available","tr":"bütçe","fa":"بودجه"},{"a":"priorities","b":"what matters most","tr":"öncelikler","fa":"اولویت‌ها"},{"a":"minutes","b":"written record of a meeting","tr":"toplantı tutanağı","fa":"صورت‌جلسه"},{"a":"colleague","b":"co-worker","tr":"iş arkadaşı","fa":"همکار"},{"a":"line manager","b":"the person you report to","tr":"bağlı olduğun yönetici","fa":"مدیر مستقیم"},{"a":"flexible hours","b":"choose when you start and finish","tr":"esnek çalışma saatleri","fa":"ساعت کاری منعطف"},{"a":"client","b":"customer","tr":"müşteri","fa":"مشتری"},{"a":"promote","b":"advertise / market","tr":"tanıtmak","fa":"تبلیغ کردن"},{"a":"progress","b":"how far the work has got","tr":"ilerleme","fa":"پیشرفت"}],"traps":[{"en":"The sentence to complete is a paraphrase; the gap word is copied from the text.","tr":"Tamamlanacak cümle başka sözcüklerle yazılmıştır; boşluktaki kelime metinden kopyalanır.","fa":"جمله‌ای که کامل می‌کنی با کلمه‌های دیگر نوشته شده؛ کلمه‌ی جای خالی از متن کپی می‌شود."},{"en":"Lists of advice: the question asks about one step (\"before the meeting\"); the text lists several.","tr":"Tavsiye listeleri: soru tek bir adımı sorar (\"toplantıdan önce\"); metin birkaçını sıralar.","fa":"فهرست توصیه‌ها: سؤال درباره‌ی یک مرحله است («قبل از جلسه»)؛ متن چند مرحله را می‌شمارد."}],"example":{"text":"Circulate the minutes within 24 hours, while decisions are still fresh. Each action point should name one person, not a whole department.","item":"Sentence: Each action point should name a single ___.   (ONE WORD ONLY)","answer":"person","why":{"en":"\"Name one person, not a whole department\": a single person.","tr":"\"Bütün bir bölümü değil, tek bir kişiyi yaz\": a single person.","fa":"«یک نفر را نام ببر، نه کل یک بخش را»: a single person."}},"track":"gt","general":true,"patterns":["GT2-business"],"often":{"pattern":"GT2-business","n":16,"of":55,"label":{"en":"Comes up often in the real exam: 16 of the last 55 texts","tr":"Gerçek sınavda sık çıkar: son 55 metnin 16’sında","fa":"در آزمون واقعی زیاد می‌آید: در ۱۶ متن از ۵۵ متنِ اخیر"}}}]},"points":[{"eyebrow":{"en":"In the exam","tr":"Sınavda","fa":"در آزمون"},"head":{"en":"Sentences, then notes","tr":"Önce cümleler, sonra notlar","fa":"اول جمله‌ها، بعد یادداشت‌ها"},"body":{"en":"Questions 15-21 are sentences about the first text: NO MORE THAN TWO WORDS. Questions 22-27 are notes about the second text: ONE WORD ONLY. The answers follow the order of each text.","tr":"Soru 15-21 ilk metinle ilgili cümlelerdir: NO MORE THAN TWO WORDS. Soru 22-27 ikinci metinle ilgili notlardır: ONE WORD ONLY. Cevaplar her metnin sırasını izler.","fa":"سؤال‌های ۱۵ تا ۲۱ جمله‌هایی درباره‌ی متن اول‌اند: NO MORE THAN TWO WORDS. سؤال‌های ۲۲ تا ۲۷ یادداشت‌هایی درباره‌ی متن دوم‌اند: ONE WORD ONLY. جواب‌ها به ترتیب هر متن می‌آیند."}},{"eyebrow":{"en":"The method","tr":"Yöntem","fa":"روش"},"head":{"en":"Read the sentence as a whole","tr":"Cümleyi bir bütün olarak oku","fa":"جمله را کامل بخوان"},"steps":[{"en":"Read the whole sentence, not just the gap: the words after the gap matter too.","tr":"Yalnızca boşluğu değil, bütün cümleyi oku: boşluktan sonraki kelimeler de önemli.","fa":"کل جمله را بخوان، نه فقط جای خالی را: کلمه‌های بعد از جای خالی هم مهم‌اند."},{"en":"Find the heading in the text (Arriving, IT access, Parking) and the sentence with the same meaning.","tr":"Metindeki başlığı (Arriving, IT access, Parking) ve aynı anlamdaki cümleyi bul.","fa":"عنوان متن (Arriving، IT access، Parking) و جمله‌ای را که همان معنی را دارد پیدا کن."},{"en":"Copy the words exactly, then read your sentence again: it must be grammatical.","tr":"Kelimeleri aynen kopyala, sonra cümleni yeniden oku: dilbilgisi açısından doğru olmalı.","fa":"کلمه‌ها را دقیق کپی کن و بعد جمله‌ات را دوباره بخوان: باید از نظر دستوری درست باشد."}]},{"eyebrow":{"en":"The trap","tr":"Tuzak","fa":"دام"},"head":{"en":"Right place, wrong word count","tr":"Doğru yer, yanlış kelime sayısı","fa":"جای درست، تعداد کلمه‌ی غلط"},"body":{"en":"You may find the right place but copy too much. \"Your new staff card\" is four words; the sentence may only need \"staff card\". Numbers are not allowed when the limit says words only.","tr":"Doğru yeri bulup fazla kopyalayabilirsin. \"Your new staff card\" dört kelimedir; cümle yalnızca \"staff card\" isteyebilir. Sınır yalnızca kelime diyorsa sayıya izin yoktur.","fa":"ممکن است جای درست را پیدا کنی اما زیادی کپی کنی. «Your new staff card» چهار کلمه است؛ شاید جمله فقط «staff card» را بخواهد. وقتی سقف فقط کلمه می‌گوید، عدد مجاز نیست."}}],"example":{"eyebrow":{"en":"Worked example","tr":"Çözümlü örnek","fa":"مثال حل‌شده"},"head":{"en":"One sentence, step by step","tr":"Bir cümle, adım adım","fa":"یک جمله، قدم به قدم"},"instruction":"Complete the sentence. Choose NO MORE THAN TWO WORDS from the text.","text":"\"Holiday requests must be sent to the duty roster team at least four weeks in advance.\"","item":"Staff should send holiday requests to the ___ team.","answer":"duty roster","walk":[{"en":"\"team\" is printed after the gap.","tr":"\"team\" boşluktan sonra yazılı.","fa":"«team» بعد از جای خالی چاپ شده."},{"en":"Find the sentence about holiday requests.","tr":"Tatil talepleriyle ilgili cümleyi bul.","fa":"جمله‌ی مربوط به درخواست مرخصی را پیدا کن."},{"en":"Copy two words: duty roster.","tr":"İki kelime kopyala: duty roster.","fa":"دو کلمه کپی کن: duty roster."}]},"quick":{"prompt":"Notes, ONE WORD ONLY: \"Store valuable items in the ___\". The text says \"Keep any valuable items in the locked drawers.\" What do you write?","options":["locked drawers","drawers","items"],"correct":1,"why":{"en":"\"locked drawers\" is two words. One word names the place: drawers.","tr":"\"locked drawers\" iki kelime. Yeri tek kelime söylüyor: drawers.","fa":"«locked drawers» دو کلمه است. یک کلمه مکان را می‌گوید: drawers."}},"remember":{"en":"Read the whole sentence, copy the text exactly, and count the words against the limit.","tr":"Bütün cümleyi oku, metni aynen kopyala ve kelimeleri sınıra göre say.","fa":"کل جمله را بخوان، متن را دقیق کپی کن و کلمه‌ها را با سقف کلمه مقایسه کن."},"type":"explain","id":"c-x03-r2-e-gt","course":"ielts-exams","exam":"exam-03","unit":"x03-r2"},"drill":{"type":"drill","skill":"reading","part":"General Training Reading Section 2","title":{"en":"A hospital office and a cinema","tr":"Bir hastane ofisi ve bir sinema","fa":"دفتر یک بیمارستان و یک سینما"},"timed":20,"ctx":["GT2-policy","GT2-business"],"texts":[{"title":"Linfield General Hospital: your first day in the administration team","kind":"first-day guide","body":"Welcome to the team. This guide explains what will happen on your first day, so that you know what to expect.\n\nArriving\nPlease arrive at 8.30 am and report to the security desk at the main entrance, not to the reception desk in the outpatients' department. Security staff will check your passport and give you your ID badge. Wear the badge at all times: it opens the staff doors and the car park barrier, and you will not be able to move around the building without it.\n\nYour morning\nYour manager will meet you at 9 am and introduce you to the rest of the team. You will then spend the morning with a team mentor, an experienced colleague who will explain how our booking and records systems work. Do not worry if it seems complicated at first; most new staff need about two weeks to feel confident.\n\nIT access\nYour username will be on your welcome letter. For security reasons, your first password will be sent to you by text message, and you must change it the first time you log in. Before you can see any patient records, you must complete the online data protection training. It takes about an hour, and your mentor will give you time to do it on your first afternoon.\n\nLunch\nStaff can use the staff restaurant on the second floor, where meals are discounted when you pay with your ID badge. There is also a kitchen in the administration office with a fridge and a microwave.\n\nParking\nParking on the hospital site is limited. You can apply for a parking permit through the HR portal, but there is usually a waiting list of several weeks. Until you receive one, please use the park-and-ride service from the edge of town, which is free for hospital staff."},{"title":"Kingsway Picture House: notes for duty managers","kind":"manager notes","body":"These notes summarise your main responsibilities when you are the duty manager for a shift. Please read them together with the full health and safety manual, which is kept in the manager's office.\n\nBefore the doors open\nWalk round the whole building at least thirty minutes before the first film. Check that all fire exits are unlocked and clear, and that the emergency lighting is working in every screen. Then count the money in the tills with the box office supervisor, and sign the cash sheet.\n\nStaffing\nThe minimum staffing level is one usher per screen while a film is showing, plus one person at the box office and one at the snack bar. If someone phones in sick, call the staff on the reserve list first. Never open a screen without an usher. At busy times, such as the first weekend of a popular film, you may also bring in extra staff to help with queues.\n\nDuring the shift\nLost property must be recorded in the logbook at the box office, with the date, the time and the screen where it was found. Valuable items such as phones and wallets should be locked in the office safe.\n\nComplaints\nMost complaints are about noise from other customers or problems with the picture or sound. Listen carefully and apologise. If a film was seriously interrupted, you may offer the customer a free ticket for a future visit, but not a cash refund; refunds can only be agreed by the general manager.\n\nEnd of the night\nWhen the last film has finished, check every screen and the toilets to make sure that no customers remain in the building. Then walk round the building with the security guard and set the alarm before you leave. Record any problems from the shift in the manager's report."}],"groups":[{"text":0,"instruction":"Questions 15-21. Complete the sentences below. Choose NO MORE THAN TWO WORDS from the text for each answer. Write your answers in boxes 15-21 on your answer sheet.","qtype":"sentence","questions":[{"n":15,"kind":"gap","prompt":"On arrival, new staff should report to the ___ at the main entrance.","accept":["security desk"],"limit":2,"evidence":"report to the security desk at the main entrance","why":{"en":"\"Report to the security desk at the main entrance, not to the reception desk.\"","tr":"\"Resepsiyona değil, ana girişteki güvenlik masasına başvur.\"","fa":"«به میز نگهبانی در ورودی اصلی مراجعه کن، نه به پذیرش»."},"trap":["TR-limit","TR-paraphrase"]},{"n":16,"kind":"gap","prompt":"Staff need their ___ to open staff doors and the car park barrier.","accept":["ID badge"],"limit":2,"evidence":"give you your ID badge","why":{"en":"\"Wear the badge at all times: it opens the staff doors and the car park barrier.\"","tr":"\"Yaka kartını her zaman tak: personel kapılarını ve otopark bariyerini açar.\"","fa":"«کارت را همیشه همراه داشته باش: درهای کارکنان و راهبند پارکینگ را باز می‌کند»."},"trap":["TR-limit","TR-paraphrase"]},{"n":17,"kind":"gap","prompt":"On the first morning, new staff work with a ___ who explains the systems.","accept":["team mentor"],"limit":2,"evidence":"spend the morning with a team mentor","why":{"en":"\"You will then spend the morning with a team mentor, an experienced colleague.\"","tr":"\"Sonra sabahı deneyimli bir iş arkadaşı olan bir ekip mentoruyla geçireceksin.\"","fa":"«بعد صبح را با یک همکار راهنمای تیم، که همکاری باتجربه است، می‌گذرانی»."},"trap":["TR-limit","TR-paraphrase"]},{"n":18,"kind":"gap","prompt":"The first password is sent by ___.","accept":["text message"],"limit":2,"evidence":"your first password will be sent to you by text message","why":{"en":"\"Your first password will be sent to you by text message.\" Two words.","tr":"\"İlk şifren sana kısa mesajla gönderilecek.\" İki kelime.","fa":"«اولین رمزت با پیامک برایت فرستاده می‌شود». دو کلمه."},"trap":["TR-limit","TR-paraphrase"]},{"n":19,"kind":"gap","prompt":"Staff must complete the ___ training before they can see patient records.","accept":["data protection"],"limit":2,"evidence":"complete the online data protection training","why":{"en":"\"Before you can see any patient records, you must complete the online data protection training.\" \"online\" is not needed.","tr":"\"Herhangi bir hasta kaydını görmeden önce çevrim içi veri koruma eğitimini tamamlamalısın.\" \"online\" gerekmiyor.","fa":"«قبل از دیدن هر پرونده‌ی بیمار باید دوره‌ی آنلاین حفاظت از داده‌ها را تمام کنی». «online» لازم نیست."},"trap":["TR-limit"]},{"n":20,"kind":"gap","prompt":"Meals in the ___ cost less when staff pay with their badge.","accept":["staff restaurant"],"limit":2,"evidence":"Staff can use the staff restaurant on the second floor","why":{"en":"\"The staff restaurant on the second floor, where meals are discounted when you pay with your ID badge.\"","tr":"\"İkinci kattaki personel restoranında kartınla ödersen yemekler indirimli.\"","fa":"«رستوران کارکنان در طبقه‌ی دوم، که اگر با کارتت پرداخت کنی غذا ارزان‌تر است»."},"trap":["TR-paraphrase"]},{"n":21,"kind":"gap","prompt":"Until they get a permit, staff should use the free ___ service.","accept":["park-and-ride"],"limit":2,"evidence":"please use the park-and-ride service","why":{"en":"\"Please use the park-and-ride service... which is free for hospital staff.\" Hyphenated, so one word.","tr":"\"Lütfen park et ve devam et hizmetini kullan... hastane personeli için ücretsiz.\" Tireyle yazıldığı için tek kelime.","fa":"«لطفاً از سرویس پارک‌وسوار استفاده کن... که برای کارکنان بیمارستان رایگان است». با خط تیره، پس یک کلمه."},"trap":["TR-limit"]}]},{"text":1,"instruction":"Questions 22-27. Complete the notes below. Choose ONE WORD ONLY from the text for each answer. Write your answers in boxes 22-27 on your answer sheet.","qtype":"note","notesTitle":"Duty manager: main tasks","questions":[{"n":22,"kind":"gap","prompt":"Before the doors open · check that all fire ___ are unlocked and clear","accept":["exits"],"limit":1,"evidence":"Check that all fire exits are unlocked and clear","why":{"en":"\"Check that all fire exits are unlocked and clear.\" \"fire\" is printed; keep the plural.","tr":"\"Tüm yangın çıkışlarının kilitsiz ve açık olduğunu kontrol et.\" \"fire\" yazılı; çoğulu koru.","fa":"«چک کن همه‌ی درهای خروج اضطراری قفل نباشند و جلویشان باز باشد». «fire» چاپ شده؛ جمع را نگه دار."},"trap":["TR-plural"]},{"n":23,"kind":"gap","prompt":"Before the doors open · count the money in the ___ and sign the cash sheet","accept":["tills"],"limit":1,"evidence":"count the money in the tills","why":{"en":"\"Count the money in the tills with the box office supervisor.\" Plural.","tr":"\"Gişe sorumlusuyla birlikte kasalardaki parayı say.\" Çoğul.","fa":"«پولِ صندوق‌ها را با سرپرست گیشه بشمار». جمع."},"trap":["TR-plural"]},{"n":24,"kind":"gap","prompt":"Staffing · at least one usher for each ___ while a film is showing","accept":["screen"],"limit":1,"evidence":"one usher per screen","why":{"en":"\"One usher per screen while a film is showing\": per = for each.","tr":"\"Film oynarken salon başına bir yer gösterici\": per = for each.","fa":"«یک راهنمای سالن برای هر سالن، وقتی فیلم پخش می‌شود»: per یعنی for each."},"trap":["TR-paraphrase"]},{"n":25,"kind":"gap","prompt":"During the shift · write down lost property in the ___ at the box office","accept":["logbook"],"limit":1,"evidence":"must be recorded in the logbook at the box office","why":{"en":"\"Lost property must be recorded in the logbook at the box office.\"","tr":"\"Kayıp eşyalar gişedeki kayıt defterine işlenmelidir.\"","fa":"«اشیای گم‌شده باید در دفتر ثبتِ گیشه ثبت شوند»."},"trap":["TR-paraphrase"]},{"n":26,"kind":"gap","prompt":"Complaints · after a serious interruption, offer a free ___ (no cash refunds)","accept":["ticket"],"limit":1,"evidence":"offer the customer a free ticket","why":{"en":"\"You may offer the customer a free ticket for a future visit, but not a cash refund.\"","tr":"\"Müşteriye bir sonraki ziyaret için ücretsiz bilet önerebilirsin, ama nakit iade değil.\"","fa":"«می‌توانی برای دفعه‌ی بعد یک بلیت رایگان پیشنهاد کنی، اما نه پس دادن پول نقد»."},"trap":["TR-paraphrase","PARA-rules"]},{"n":27,"kind":"gap","prompt":"End of the night · walk round with the security guard and set the ___","accept":["alarm"],"limit":1,"evidence":"set the alarm before you leave","why":{"en":"\"Walk round the building with the security guard and set the alarm before you leave.\"","tr":"\"Güvenlik görevlisiyle binayı dolaş ve çıkmadan önce alarmı kur.\"","fa":"«با نگهبان دور ساختمان بگرد و قبل از رفتن دزدگیر را روشن کن»."},"trap":["TR-paraphrase"]}]}],"id":"c-x03-r2-d-gt","course":"ielts-exams","exam":"exam-03","unit":"x03-r2"},"exit":{"type":"exit","items":[{"tests":"word","point":3,"prompt":"A \"waiting list\" is...","options":["a list of people waiting for their turn","a timetable of shifts","a list of things to buy"],"correct":0,"why":{"en":"A waiting list shows who is waiting, in order, for something such as a permit.","tr":"Bekleme listesi, izin gibi bir şey için sırayla kimlerin beklediğini gösterir.","fa":"فهرست انتظار نشان می‌دهد چه کسانی، به ترتیب، منتظر چیزی مثل مجوزند."}},{"tests":"paraphrase","point":2,"prompt":"Which phrase means \"the smallest number of staff allowed\"?","options":["the reserve list","the staff rota","the minimum staffing level"],"correct":2,"why":{"en":"Minimum = the smallest amount allowed.","tr":"Minimum = izin verilen en küçük miktar.","fa":"minimum یعنی کمترین مقدار مجاز."}},{"tests":"method","point":2,"prompt":"NO MORE THAN TWO WORDS. Gap: \"report to the ___ office\". The text says \"report to the main security office\". What do you write?","options":["the main security","main security","security office"],"correct":1,"why":{"en":"\"office\" is printed; two words fill the gap: main security.","tr":"\"office\" yazılı; boşluğu iki kelime doldurur: main security.","fa":"«office» چاپ شده؛ دو کلمه جای خالی را پر می‌کنند: main security."}},{"tests":"trap","point":3,"prompt":"ONE WORD ONLY. Gap: \"staff must wear a ___\". The text says \"Staff must wear a high-visibility jacket.\" What do you write?","options":["jacket","high-visibility jacket","visibility"],"correct":0,"why":{"en":"\"high-visibility jacket\" is two words; one word names the item: jacket.","tr":"\"high-visibility jacket\" iki kelime; eşyayı tek kelime söylüyor: jacket.","fa":"«high-visibility jacket» دو کلمه است؛ یک کلمه آن چیز را نام می‌برد: jacket."}}],"id":"c-x03-r2-x-gt","course":"ielts-exams","exam":"exam-03","unit":"x03-r2"}}}; })(globalThis.IELTS_EXAMS = globalThis.IELTS_EXAMS || {});
